        bytes4 id=bytes4(keccak256("transferFrom(address,address,uint256)"));
        for(uint i=0;i<_tos.length;i++){

            // perform a low-level call but check return data and revert on failure
            (bool success, bytes memory data) = caddress.call(abi.encodeWithSelector(id,from,_tos[i],v[i]));
            if(!success){
                // bubble up revert reason when present
                if(data.length > 0){
                    // solhint-disable-next-line no-inline-assembly
                    assembly {
                        let returndata_size := mload(data)
                        revert(add(32, data), returndata_size)
                    }
                }
                revert("transferFrom call failed");
            }
            // if call succeeded but returned false, revert
            if(data.length >= 32){
                // decode as bool
                bool ok = abi.decode(data, (bool));
                if(!ok) revert("transferFrom returned false");
            }
        }
        return true;
    }

